// ===================== CONFIG (confirm these 3 things) =====================
const BASE = 'https://api.leadmailbox.com/v2';
// (1) PATCH key for MAIN Lead Status — CONFIRM with Dan: 'status' | 'statusid' | 'leadstatus'
const STATUS_KEY = 'status';
// (2) disposition -> { status: LMB main Lead Status to set, label: field_121 value, booked }
//     David creates the 'AI - *' statuses in LMB and picks SALES_BOOKED_STATUS.
const SALES_BOOKED_STATUS = 'Contact';   // <-- David: the sales-rep entry status for a booked appt
const MAP = {
  'qualified booked':     { status: SALES_BOOKED_STATUS,   label: 'Qualified Booked',       booked: true  },
  'qualified didnt book': { status: 'AI - Qualified No Book', label: "Qualified - Didn't Book", booked: false },
  'unqualified':          { status: 'AI - Unqualified',    label: 'Unqualified',            booked: false },
  'not interested':       { status: 'AI - Not Interested', label: 'Not Interested',         booked: false },
  'busy':                 { status: 'AI - Busy',           label: 'Busy',                   booked: false },
  'voicemail':            { status: 'AI - Voicemail',      label: 'Voicemail',              booked: false },
  'wrong contact':        { status: 'AI - Wrong Contact',  label: 'Wrong Contact',          booked: false },
  'call failed':          { status: 'AI - Call Failed',    label: 'Call Failed',            booked: false },
  'other':                { status: 'AI - Other',          label: 'Other',                  booked: false }
};
// (3) round-robin pool for booked leads (David, Mike). Counter persists in workflow static data.
const ROUND_ROBIN = [100173, 107230];
// =========================================================================

const clean = (s) => (s || '').toString().toLowerCase()
  .replace(/[‘’ʼ']/g, '')
  .replace(/[‐-―-]/g, ' ')
  .replace(/\s+/g, ' ').trim();

const body = $json.body || {};
const c = body.customData || body || {};
const leadid = c.leadid || c.lead_id || body.leadid || null;
const disp = clean(c.stage_name || c.disposition || c.call_category);
const m = MAP[disp] || null;

let userid = null;
if (m && m.booked) {
  const sd = $getWorkflowStaticData('global');
  sd.rr = ((typeof sd.rr === 'number' ? sd.rr : -1) + 1) % ROUND_ROBIN.length;
  userid = ROUND_ROBIN[sd.rr];
}

return [{ json: {
  base: BASE,
  leadid: leadid,
  ready: !!(m && leadid),
  status_key: STATUS_KEY,
  status_value: m ? m.status : null,
  field_121: m ? m.label : null,                 // AI Status
  field_122: c.appointment || null,              // AI Appointment (booked time)
  field_123: c.transcript_url || null,           // AI Transcript (URL)
  field_124: c.recording_url || null,            // AI Recording (URL)
  field_125: c.summary || c.ai_summary || null,  // AI Summary
  note: c.note_html || c.note || null,
  userid: userid,
  disposition_in: disp,
  raw: c
}}];
